const rows = $input.all().map(i => i.json);

// Chi tinh tren cac lenh da dong (co ket qua ro rang)
const closed = rows.filter(r => ['TP1_HIT','TP2_HIT','SL1_HIT','SL2_HIT'].includes(r.outcome));

function computeReturn(r) {
  const entry = parseFloat(r.entry_price);
  const exit = parseFloat(r.exit_price);
  if (!entry || !exit) return null;
  return r.direction === 'BUY' ? ((exit - entry) / entry) * 100 : ((entry - exit) / entry) * 100;
}

function mean(arr) { return arr.reduce((a, b) => a + b, 0) / arr.length; }
function stdev(arr) {
  const m = mean(arr);
  return Math.sqrt(mean(arr.map(x => (x - m) ** 2)));
}
function sharpe(returns) {
  if (returns.length < 2) return null;
  const sd = stdev(returns);
  return sd === 0 ? null : mean(returns) / sd;
}
function sortino(returns) {
  const downside = returns.filter(r => r < 0);
  if (downside.length === 0) return null;
  const downsideDev = Math.sqrt(mean(downside.map(r => r * r)));
  return downsideDev === 0 ? null : mean(returns) / downsideDev;
}
function maxDrawdown(returnsInOrder) {
  let equity = 100, peak = 100, maxDD = 0;
  for (const r of returnsInOrder) {
    equity *= (1 + r / 100);
    peak = Math.max(peak, equity);
    const dd = (peak - equity) / peak * 100;
    maxDD = Math.max(maxDD, dd);
  }
  return maxDD;
}

function computeMetrics(trades, label) {
  const withReturns = trades
    .map(t => ({ ...t, ret: computeReturn(t) }))
    .filter(t => t.ret !== null)
    .sort((a, b) => new Date(a.entry_time) - new Date(b.entry_time));

  if (withReturns.length === 0) return null;

  const returns = withReturns.map(t => t.ret);
  const wins = returns.filter(r => r > 0);
  const losses = returns.filter(r => r < 0);
  const winRate = wins.length / returns.length;
  const avgWin = wins.length ? mean(wins) : 0;
  const avgLoss = losses.length ? Math.abs(mean(losses)) : 0;

  let kelly = null;
  if (avgLoss > 0) {
    const R = avgWin / avgLoss;
    kelly = winRate - (1 - winRate) / R;
  }

  return {
    symbol: label,
    total_trades: returns.length,
    win_rate_pct: Math.round(winRate * 10000) / 100,
    avg_win_pct: Math.round(avgWin * 100) / 100,
    avg_loss_pct: Math.round(avgLoss * 100) / 100,
    sharpe_ratio: sharpe(returns) !== null ? Math.round(sharpe(returns) * 1000) / 1000 : null,
    sortino_ratio: sortino(returns) !== null ? Math.round(sortino(returns) * 1000) / 1000 : null,
    max_drawdown_pct: Math.round(maxDrawdown(returns) * 100) / 100,
    kelly_pct: kelly !== null ? Math.round(kelly * 10000) / 100 : null,
    half_kelly_pct: kelly !== null ? Math.round(kelly * 5000) / 100 : null
  };
}

const results = [];

// Tinh rieng cho tung symbol
const bySymbol = {};
for (const t of closed) {
  if (!bySymbol[t.symbol]) bySymbol[t.symbol] = [];
  bySymbol[t.symbol].push(t);
}
for (const symbol in bySymbol) {
  const m = computeMetrics(bySymbol[symbol], symbol);
  if (m) results.push(m);
}

// Tinh tong the toan bo danh muc
const overall = computeMetrics(closed, 'PORTFOLIO');
if (overall) results.push(overall);

return results.map(r => ({ json: r }));
